WITH with_windows AS (SELECT *, LEAD(balance) OVER (PARTITION BY customer_id ORDER BY balance, id) AS next_balance, LAG(balance) OVER (PARTITION BY customer_id ORDER BY balance, id) AS prev_balance, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY balance, id) AS row_seq, FIRST_VALUE(balance) IGNORE NULLS OVER (PARTITION BY account_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_balance FROM accounts) SELECT s.id, s.customer_id, s.account_type, s.balance, s.opened_date, s.status, s.next_balance, s.prev_balance, s.row_seq, (SELECT SUM(t2.discount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_discount FROM with_windows s;
